import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"31、【咸】 艮下兑上","description":"周易尚氏学 - 31、【咸】 艮下兑上","frontmatter":{"title":"31、【咸】 艮下兑上","description":"周易尚氏学 - 31、【咸】 艮下兑上"},"headers":[],"relativePath":"zh/classics/shangshi/036.md","filePath":"zh/classics/shangshi/036.md"}'),h={name:"zh/classics/shangshi/036.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_31、【咸】-艮下兑上" tabindex="-1">31、【咸】 艮下兑上 <a class="header-anchor" href="#_31、【咸】-艮下兑上" aria-label="Permalink to “31、【咸】 艮下兑上”">​</a></h1><p>咸感也。归藏曰钦。诗秦风忧心钦钦。传思望之。心中钦钦然。盖以少男仰求少女。有钦慕之情。是钦亦有感意。与咸义同。六爻皆有应。故曰亨利贞。少女在前。肖男在后。而艮为求。兑为悦。艮男求女。兑悦应之。得婚姻之正。故曰取女吉。</p><p>彖曰。咸。感也。柔上而刚下。二气感应以相与。止而悦。男下女。是以亨利贞。取女吉也。天地感而万物化生。圣人感人心而夫下和平。观其所感。而天地万物之情可见矣。</p><p>否三上交。故曰柔上而刚下。山泽通气。故曰二气感应以相与。艮止兑悦。故曰止而悦。兑上艮下。故曰男下女。天地感即阴阳和合。和合则万物生。圣人感人则仁义兼施。仁义侠（左水）则天下和平。盖天地万物之事。莫不由感而通。由感而成。而其所以能感之故则情也。故曰其情可见。</p><p>象曰。山上有泽。咸。君子以虚受人。</p><p>艮为君子。艮男下兑女。卑以自牧。故曰以虚受人。虞翻曰。否坤为虚。乾为人。今坤虚。三受上。故以虚受人。</p><p>初六。咸其拇。</p><p>拇。释文马郑薛云。足大指也。初在下震交。故曰成其拇。咸及拇。则欲行矣。</p><h3 id="象曰。咸其拇。志在外也。" tabindex="-1">象曰。咸其拇。志在外也。 <a class="header-anchor" href="#象曰。咸其拇。志在外也。" aria-label="Permalink to “象曰。咸其拇。志在外也。”">​</a></h3><p>外谓四。初应在四。初四相上下。则各当其位。足者人所恃以行。今感在拇。故欲之外也。巽伏故亦为志。见易林。亦失传象也。</p><p>六二。成其腓。凶。居吉。</p><p>胫腓所恃以行。感及于腓。则欲前进。乃进而凶者何也。按二当位。承阳有应。与革二至上同。革六二征吉。此应与之同。然而凶者。以革义取革新。故利于征。若咸则义取阴阳相感。感在五为正应。乃三四亦阳。二独与五。则为三四所忌。故动凶居吉。此与同人六二同。二同于五。原为正应。然而吝者。以三四亦阳。二不与同而独同五。则招忌也。其故皆在三四。近比三则失五之正应。远应五则有近不承阳之嫌。遁六二蛰以牛革。亦戒其动。以遁二与同人咸体同也。腓。说文胫端（左月）也。喘（左月）。说文腓肠也。段玉裁云。腓肠谓胫骨后之肉。肿之言肥。似中有肠者。故曰腓肠。按段释腓肠。至为明晰。即今俗所谓腿肚也。庄子天下篇。禹腓无跋（左月）。注跋（左月）细毛也。腓因劳受摩揩。故跋（左月）不生。然则腓为胫肚明矣。人之行恃胫。感及于胫。必前进矣、进则有咎。故曰凶。居则不动而承阳。故曰居吉。此爻凶义。鲜有详其故者。崔憬谓二应五。失艮止义。惠栋谓二比三。失五正应。义皆未备。</p><h3 id="象曰。虽凶居吉。顺不害也。" tabindex="-1">象曰。虽凶居吉。顺不害也。 <a class="header-anchor" href="#象曰。虽凶居吉。顺不害也。" aria-label="Permalink to “象曰。虽凶居吉。顺不害也。”">​</a></h3><p>二承阳有应。当位。本无凶理。象辞恐人生疑。故释其故。言爻辞虽云动凶居吉。然阴顺阳为天职。六二但上承诸阳。亦无害也。传意似重近取。不必远应也。翼经之大。莫过于是。</p><p>九三。咸其股。执其随。往吝。</p><p>巽为股。股在腓上。故咸及于股。阳遇阳则窒。上虽有应。不能往也。往则为四五所忌而吝生矣。若初二则随三者也。三下履重阴。止于是可矣。执者止也。止于三下比于阴。不必前进。否则吝穷也。</p><h3 id="象曰。咸其股。亦不处也。志在随人。所执下也。" tabindex="-1">象曰。咸其股。亦不处也。志在随人。所执下也。 <a class="header-anchor" href="#象曰。咸其股。亦不处也。志在随人。所执下也。" aria-label="Permalink to “象曰。咸其股。亦不处也。志在随人。所执下也。”">​</a></h3><p>股所以行。故曰不处。巽为志。乾为人。言初二志在随三。故三之所执。宜于下也。</p><p>九四。贞吉。悔亡。憧憧往来。朋从尔思。</p><p>四不当位。承乘皆阳。故必贞定无为。方免悔吝。朋谓初。尔谓四。憧撞思不定也。盖四来应初则三害之。初往应四。则二害之。故初四不宜动。宜静。然阻愈多则感愈切。朋从尔思者。言初不得应阳。而慕思四也。</p><h3 id="象曰。贞吉悔亡。未感害也。憧憧往来。未光大也。" tabindex="-1">象曰。贞吉悔亡。未感害也。憧憧往来。未光大也。 <a class="header-anchor" href="#象曰。贞吉悔亡。未感害也。憧憧往来。未光大也。" aria-label="Permalink to “象曰。贞吉悔亡。未感害也。憧憧往来。未光大也。”">​</a></h3><p>下系云。凡易之情。近而不相得则凶。或害之。三近四。二近初。然三亦阳。为四敌。二亦阴。为初敌。故二三为初四害。知其害而不动。害斯免矣。故曰未感害也。初四相上下成离。离为光大。今不能相上下。故曰未光大。</p><p>九五。咸其每（左月）。无悔。</p><p>每（左月）。说文背脊肉也。郑虞同。伏艮。艮为背。故曰咸每（左月）当位得中。故无悔。感居人身之上。故象曰志末。末谓上六。言九五感上。近而无阻。故无悔也。案五正应在二。而舍二感上者。以三四害之也。</p><h3 id="象曰。咸其每-左月-。志末也。" tabindex="-1">象曰。咸其每（左月）。志末也。 <a class="header-anchor" href="#象曰。咸其每-左月-。志末也。" aria-label="Permalink to “象曰。咸其每（左月）。志末也。”">​</a></h3><p>大过云。本末弱。以上为末也。兹曰志末。谓五为三四所阻。不能应二。故舍远取近。感在上也。</p><p>上六。咸其辅颊舌。</p><p>虞翻曰。耳目之间日辅颊。按说文。辅。人颊车也。颊。面旁也。左传辅车相依注。辅输颊。车牙车。正义云。易以辅颊舌三进并言。则三物也。故郑注颐卦云。颐者口车辅也。震动于下。又止于上。口车动而上。因输嚼物以养人。按郑所谓口车即牙车。牙车在口下。故曰动而上。辅在口上。故曰因辅嚼物以养人。是辅与牙车对。在口中，颊在面旁。居口上。与颐连。不过颊在上。颐在下。颊以骨言。颐以肉言耳。是输与颊确为二物。又皆为口之属。故与舌并言。兑为口为言。辅颊舌皆兑象。所用以言者。感及于是。则言说多矣。故象日滕口说。来矣鲜云。舌动则辅应而颊随之。三者相须用事。皆所以言者。皆兑象。</p><h3 id="象曰。咸其辅颊舌。滕口说也。" tabindex="-1">象曰。咸其辅颊舌。滕口说也。 <a class="header-anchor" href="#象曰。咸其辅颊舌。滕口说也。" aria-label="Permalink to “象曰。咸其辅颊舌。滕口说也。”">​</a></h3><p>释文。滕达也。九家作乘。虞作滕。郑云送也。按郑虞说非也。朱子云。滕与腾通。即达也。李鼎祚本正作腾。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
